from spelare import Spelare


def rad_till_spelare(rad):
    """Gör om en rad från filen till ett Spelare-objekt.
    Returnerar objektet, eller None om raden inte är godkänd."""
    rad = rad.strip()
    if rad == "":
        print("Rad ignorerad pga: Tom rad")
        return None
    delar = rad.split(";")

    # Se till att programmet också kan ignorera rader med fel antal delar, 
    # eller där namn är tomma strängen, med egna felmeddelanden!

    try:
        namn = delar[0].strip()
        poäng = int(delar[1])
    except ValueError:
        print("Rad ignorerad pga: Ogiltig poäng")
        return None
    return Spelare(namn, poäng)

def läs_spelare(filnamn):
    """Läser spelarna från filen filnamn.
    Returnerar en lista med Spelare-objekt."""
    spelarlista = []
    felaktiga = 0
    with open(filnamn, "r") as fil:
        for rad in fil:
            spelaren = rad_till_spelare(rad)
            if spelaren != None:
                spelarlista.append(spelaren)
            else:
                felaktiga += 1
    return spelarlista, felaktiga

def skriv_spelare(filnamn, spelarlista):
    """Skriver alla spelare i spelarlista till filen filnamn, en spelare per rad.
    Returnerar antalet spelare som skrevs."""
    with open(filnamn, "w") as fil:
        for spelaren in spelarlista:
            fil.write(spelaren.till_rad() + "\n")
    return len(spelarlista)

class Spelare:

    def __init__(self, namnet, poängen):
        """Skapar en spelare med ett namn (sträng) och en poäng (heltal)."""
        self.namn = namnet
        self.poäng = poängen

    def mer_poäng(self):
        """Ger spelaren en poäng till."""
        self.poäng += 1

    def till_rad(self):
        """Returnerar spelaren som en rad till filen, t.ex. "Emma;23"."""
        return self.namn + ";" + str(self.poäng)

    def __str__(self):
        """Returnerar en text om spelaren, t.ex. "Emma har 23 poäng"."""
        return self.namn + " har " + str(self.poäng) + " poäng"
